item.content:encoded:
#nd_options_navigation_4_top_header {
background: rgb(27,188,155); 
background: -moz-linear-gradient(45deg, rgba(27,188,155,0.9) 0%, rgba(27,188,155,0.9) 35%, rgba(37,195,252,0.9) 100%); 
background: -webkit-linear-gradient(45deg, rgba(27,188,155,0.9) 0%,rgba(27,188,155,0.9) 35%,rgba(37,195,252,0.9) 100%); 
background: linear-gradient(45deg, rgb(236, 186, 190) 0%,rgb(224, 174, 177) 35%,rgb(138, 198, 208) 100%);
filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#1bbc9b', endColorstr='#25c3fc',GradientType=1 );
}

#nd_options_navigation_4_top_header {
background: rgb(27,188,155); 
background: -moz-linear-gradient(45deg, rgba(27,188,155,0.9) 0%, rgba(27,188,155,0.9) 35%, rgba(37,195,252,0.9) 100%); 
background: -webkit-linear-gradient(45deg, rgba(27,188,155,0.9) 0%,rgba(27,188,155,0.9) 35%,rgba(37,195,252,0.9) 100%); 
background: linear-gradient(45deg, rgb(236, 186, 190) 0%,rgb(224, 174, 177) 35%,rgb(138, 198, 208) 100%);
filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#1bbc9b', endColorstr='#25c3fc',GradientType=1 );
}

.hide, .cacher {
	display: none !important;
}

h2 {
	line-height: 30px;
}

h3 {
	line-height: 25px;
}

p {
	margin-bottom: 20px;
	text-align: justify;
}

ol li {
	margin-top: 10px;
}

.parent-pageid-30 h1 {
	display: none;
}

.parent-pageid-30 #nd_options_footer_4 {
	display: none;
}

#nd_options_navigation_4_container li a {
	line-height: 17px;
}

.page-id-30 .post-30.page.type-page a {
	font-family: 'Playfair Display', sans-serif;
	color: #727475;
}

.page-id-994 .nd_options_container h1 {
	display: none;
}

.nom-temoignage {
	font-size: 21pt !important;
	color: #727475;
	font-family: 'Playfair Display', sans-serif;
	margin-bottom: 20px;
	margin-top: 10px;
}

.texte-temoignage {
	font-style: italic;
}

.en-tete-temoignages p,
.en-tete-temoignages ul li {
	font-size: 13pt;
	color: #727475;
	font-family: 'Open Sans', sans-serif;
}

#nd_options_footer_4 {
	border-top: 0px !important;
}

#nd_options_footer_4_copyright .grid.nd_options_grid_6.nd_options_text_align_right.nd_options_text_align_center_responsive .nd_options_font_size_14.nd_options_line_height_25_responsive {
	display: none;
}

.page-id-949 input[type=submit] {
	font-weight: bold;
}

.page-id-949 .post-949.page.type-page.status-publish.hentry h1 {
	display: none;
}

.nd_options_container.nd_options_padding_0_15.nd_options_box_sizing_border_box.nd_options_clearfix h1 {
	display: none;
}

.home .nd_options_section.nd_options_height_50,
.home .nd_options_section.nd_options_height_20 {
	display: none;
}

.home .blocks-home a {
	font-family: "Open Sans", sans-serif;
	color: #ffffff;
	text-transform: uppercase;
	letter-spacing: 3px;
	font-size: 17px;
	font-weight: lighter;
	text-shadow: 1px 1px 10px #000000;
}

.home .blocks-home p {
	text-align: center;
}

@media only screen and (max-device-width: 1100px) {
     .home .nd_options_container.nd_options_padding_0_15.nd_options_box_sizing_border_box.nd_options_clearfix {
          width: 100%;
     } 

}
